#!/usr/bin/env python3
# patch-158-G12: merge Totals + Payment; fix stale totals + banner
"""
Three related bugs, one underlying cause: the Totals card and
Payment card were two separate units using two different sources
of truth, and a stale payment_status column was being trusted.

  Symptoms before:
    1. Totals card showed Subtotal $450 (services only); Payment
       card showed Total $533.98 (with tax + parts). They could
       disagree because they computed differently.
    2. After a deposit equal to original total, payment_status
       got set to "paid". Adding parts/charges later pushed total
       higher but payment_status was never recomputed, so the top
       banner kept saying "Paid in full" even with balance owed.
    3. Editing a part quantity recalculated the snapshot server-
       side but only updated the line-total cell client-side; the
       Totals card stayed stale until reload.

  Fixes:
    - Merge Totals + Payment into one card. Schedule and Internal
       note remain as their own cards below.
    - Single source of truth: $appointment->subtotal_cents,
       tax_cents, total_cents, paid_cents. Always kept fresh by
       recalcAppointmentTotals() on every mutating op.
    - Parts count surfaced in the counts list (was missing).
    - "Paid in full" banner now derived from
       paid_cents >= total_cents AND total_cents > 0,
       ignoring the stale payment_status column.
    - Part qty edit now reloads on success so the Totals card
       reflects the new snapshot, matching add/remove behavior.

Single-file view patch. No backend changes.
"""
import argparse, base64, pathlib, sys

MARKER = "MARKER-PATCH-158-G12"

